    });

    const chipRows: [string, () => string, string][] = [
      ['/co/datos', co, 'Colombia'],
      ['/cl/planes', cl, 'Chile'],
    ];

    it.each(chipRows)('US-04-AC-28 at %s the header has exactly one link, named "Cambiar país (actual: %s)", with the address "/", the country name as text and the flag hidden from assistive technology', async (address, entry, country) => {
      await start(entry());
