      expect(shownValue(control(app.root, 'Placa'))).toBe('ABC123');
    });

    const tabRows: [string, () => string, string][] = [
      ['/co/datos', step1Only, 'Cambiar país'],
      ['/co/planes', step1Only, 'Volver a tus datos'],
      ['/co/resumen', co, 'Volver a planes'],
