    await page.keyboard.press('Tab');
    await expect(page.getByRole('link', { name: 'Colombia', exact: true })).toBeFocused();
    await page.keyboard.press('Tab');
    await expect(page.getByRole('link', { name: 'Chile', exact: true })).toBeFocused();
