/*
 * Global styles: reset, element defaults, focus, buttons, the input look shared by every control,
 * skeletons, the page enter animation and the panels of the CDK overlays (ADR-0010, ADR-0013).
 * Semantic and component tokens only; no primitive and no loose value (US-04-BR-01).
 */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background-color: var(--color-bg);
  background-image: var(--texture-dots);
  background-size: var(--texture-dots-gap) var(--texture-dots-gap);
  color: var(--color-text);
  font-family: var(--font-text);
  font-size: var(--text-body);
  line-height: var(--leading-body);
}

/* ---- Type ------------------------------------------------------------------------------- */

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: var(--weight-bold);
}

/* The page heading: large, heavy, semi-expanded, with a soft gradient (ADR-0010 section 5). */
h1 {
  font-size: var(--text-display);
import type { RGB, RGBA } from './contrast';
import { hexToRgb } from './contrast';

export interface Decl {
  /** Identifier of the innermost block (see `Block.id`), -1 at the top level. */
  blockId: number;
  /** The preludes of the enclosing blocks, outermost first (`['@media (...)', '.card']`). */
  stack: string[];
  prop: string;
  value: string;
}

export interface Block {
  /** Position of the block in the file, so two blocks with the same prelude stay apart. */
  id: number;
  stack: string[];
  prelude: string;
}

export function stripComments(css: string): string {
  return css.replace(/\/\*[\s\S]*?\*\//g, '');
}

